func displayNodeID(id string) string {
	if len(id) >= 8 && id[:8] == "muxcore-" {
		id = id[8:]
	}
	if len(id) > 0 && id[0] == ':' {
		return "localhost" + id
	}
	return id
}

func nodeAvatar(id string) string {
	for _, ch := range id {
		if ch >= 'a' && ch <= 'z' {
			return string(ch - 32)
		}
		if ch >= 'A' && ch <= 'Z' {
			return string(ch)
		}
		if ch >= '0' && ch <= '9' {
			return string(ch)
		}
	}
	if len(id) > 0 {
		return id[:1]
	}
	return "N"
}

